        ));
    arrList.Add(
        new Student
        (
            FirstName: "Claire",
            LastName: "O’Donnell",
            ExamScores: new int[] { 75, 84, 91, 39 }
        ));
    arrList.Add(
        new Student
        (
            FirstName: "Sven",
            LastName: "Mortensen",
            ExamScores: new int[] { 88, 94, 65, 91 }
        ));
    arrList.Add(
        new Student
        (
            FirstName: "Cesar",
            LastName: "Garcia",
            ExamScores: new int[] { 97, 89, 85, 82 }
        ));

    var query = from Student student in arrList
                where student.ExamScores[0] > 95
                select student;

