    public static async Task ConsumerAsyncBlock()
    {
        while (true)
        {
            int nextItem = await m_dataBlock.ReceiveAsync();
            Stubs.ProcessNextItem(nextItem);
        }
    }

    public static void ProduceBlock(int data)
    {
        m_dataBlock.Post(data);
    }
```

